def {{fn_name}}(graph):
    disc = {}
    low = {}
    bridges = []
    timer = [0]
    def dfs(u, parent):
        disc[u] = low[u] = timer[0]; timer[0] += 1
        for v in graph.get(u, []):
            if v == parent: continue
            if v in disc:
                low[u] = min(low[u], disc[v])
            else:
                dfs(v, u)
                low[u] = min(low[u], low[v])
                if low[v] > disc[u]:
                    bridges.append((u, v))
    for u in graph:
        if u not in disc:
            dfs(u, None)
    return bridges
